CREATE TABLE IF NOT EXISTS actas_recepcion (
    id integer DEFAULT nextval('actas_recepcion_id_seq'::regclass) NOT NULL,
    fecha date NOT NULL,
    tipo_documento character varying,
    numero_documento character varying,
    cliente_id integer NOT NULL,
    proveedor character varying,
    tipo_operacion character varying,
    tipo_conteo character varying,
    condicion_temperatura character varying,
    observaciones text,
    responsable_recepcion character varying,
    responsable_entrega character varying,
    jefe_almacen character varying,
    estado character varying DEFAULT 'activa'::character varying NOT NULL,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);


CREATE TABLE IF NOT EXISTS actas_recepcion_detalles (
    id integer DEFAULT nextval('actas_recepcion_detalles_id_seq'::regclass) NOT NULL,
    acta_id integer NOT NULL,
    producto_id integer NOT NULL,
    producto_codigo character varying,
    producto_nombre character varying,
    fabricante character varying,
    lote_numero character varying NOT NULL,
    fecha_vencimiento date,
    um character varying,
    temperatura_min numeric,
    temperatura_max numeric,
    cantidad_solicitada numeric DEFAULT 0 NOT NULL,
    cantidad_recibida numeric DEFAULT 0 NOT NULL,
    cantidad_bultos numeric DEFAULT 0,
    cantidad_cajas numeric DEFAULT 0,
    cantidad_por_caja numeric DEFAULT 0,
    cantidad_fraccion numeric DEFAULT 0,
    aspecto character varying DEFAULT 'EMB'::character varying NOT NULL,
    observaciones text,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);

