CREATE TABLE IF NOT EXISTS ajustes_stock (
    id integer DEFAULT nextval('ajustes_stock_id_seq'::regclass) NOT NULL,
    producto_id integer NOT NULL,
    tipo character varying NOT NULL,
    cantidad numeric NOT NULL,
    motivo character varying NOT NULL,
    observaciones text,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);

CREATE TABLE IF NOT EXISTS alertas_vencimiento (
    id integer DEFAULT nextval('alertas_vencimiento_id_seq'::regclass) NOT NULL,
    lote_id integer,
    producto_id integer NOT NULL,
    lote_numero character varying NOT NULL,
    fecha_vencimiento date NOT NULL,
    estado character varying DEFAULT 'VIGENTE'::character varying NOT NULL,
    dias_faltantes integer,
    leida smallint DEFAULT 0 NOT NULL,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    dias_para_vencer integer,
    cantidad integer DEFAULT 0
);

CREATE TABLE IF NOT EXISTS auditorias (
    id integer DEFAULT nextval('auditorias_id_seq'::regclass) NOT NULL,
    usuario_id integer,
    accion character varying NOT NULL,
    tabla_afectada character varying NOT NULL,
    registro_id integer,
    valores_anteriores jsonb,
    valores_nuevos jsonb,
    ip_address character varying,
    user_agent text,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);


CREATE TABLE IF NOT EXISTS clientes (
    id integer DEFAULT nextval('clientes_id_seq'::regclass) NOT NULL,
    codigo character varying NOT NULL,
    razon_social character varying NOT NULL,
    cuit character varying,
    direccion character varying,
    distrito character varying,
    provincia character varying,
    departamento character varying,
    categoria_riesgo character varying,
    estado character varying DEFAULT 'Activo'::character varying NOT NULL,
    telefono character varying,
    email character varying,
    activo smallint DEFAULT 1 NOT NULL,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    persona_contacto character varying
);


CREATE TABLE IF NOT EXISTS kardex (
    id integer DEFAULT nextval('kardex_id_seq'::regclass) NOT NULL,
    producto_id integer NOT NULL,
    lote_numero character varying,
    tipo_movimiento character varying NOT NULL,
    cantidad numeric NOT NULL,
    saldo numeric NOT NULL,
    documento_tipo character varying,
    documento_numero character varying,
    referencia_id integer,
    observaciones text,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);


CREATE TABLE IF NOT EXISTS lotes (
    id integer DEFAULT nextval('lotes_id_seq'::regclass) NOT NULL,
    producto_id integer NOT NULL,
    numero_lote character varying NOT NULL,
    fecha_vencimiento date,
    cantidad_ingresada numeric DEFAULT 0 NOT NULL,
    cantidad_disponible numeric DEFAULT 0 NOT NULL,
    nota_ingreso_id integer,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    cantidad_inicial numeric,
    cantidad_actual numeric,
    estado character varying DEFAULT 'ACTIVO'::character varying
);


CREATE TABLE IF NOT EXISTS nota_ingreso_detalles (
    id integer DEFAULT nextval('nota_ingreso_detalles_id_seq'::regclass) NOT NULL,
    nota_ingreso_id integer NOT NULL,
    producto_id integer NOT NULL,
    lote_numero character varying NOT NULL,
    fecha_vencimiento date,
    um character varying,
    fabricante character varying,
    temperatura_min_c numeric,
    temperatura_max_c numeric,
    cantidad numeric NOT NULL,
    precio_unitario numeric,
    cantidad_bultos numeric DEFAULT 0,
    cantidad_cajas numeric DEFAULT 0,
    cantidad_por_caja numeric DEFAULT 0,
    cantidad_fraccion numeric DEFAULT 0,
    cantidad_total numeric DEFAULT 0,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);


CREATE TABLE IF NOT EXISTS nota_salida_detalles (
    id integer DEFAULT nextval('nota_salida_detalles_id_seq'::regclass) NOT NULL,
    nota_salida_id integer NOT NULL,
    producto_id integer NOT NULL,
    lote_id integer,
    cantidad numeric NOT NULL,
    precio_unitario numeric,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    cant_bulto numeric DEFAULT 0,
    cant_caja numeric DEFAULT 0,
    cant_x_caja numeric DEFAULT 0,
    cant_fraccion numeric DEFAULT 0,
    lote_numero character varying,
    fecha_vencimiento date,
    um character varying,
    fabricante character varying,
    temperatura_min_c numeric,
    temperatura_max_c numeric,
    cantidad_total numeric
);


CREATE TABLE IF NOT EXISTS notas_ingreso (
    id integer DEFAULT nextval('notas_ingreso_id_seq'::regclass) NOT NULL,
    numero_ingreso character varying NOT NULL,
    fecha date NOT NULL,
    proveedor character varying NOT NULL,
    tipo_documento character varying,
    numero_documento character varying,
    responsable_id integer,
    estado character varying DEFAULT 'REGISTRADA'::character varying NOT NULL,
    observaciones text,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    cliente_id integer,
    numero_guia character varying,
    cliente_ruc character varying
);


CREATE TABLE IF NOT EXISTS notas_salida (
    id integer DEFAULT nextval('notas_salida_id_seq'::regclass) NOT NULL,
    numero_salida character varying NOT NULL,
    cliente_id integer,
    fecha date NOT NULL,
    tipo_documento character varying,
    numero_documento character varying,
    fecha_ingreso date,
    motivo_salida text,
    responsable_id integer,
    estado character varying DEFAULT 'REGISTRADA'::character varying NOT NULL,
    observaciones text,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    cliente_ruc character varying
);


CREATE TABLE IF NOT EXISTS productos (
    id integer DEFAULT nextval('productos_id_seq'::regclass) NOT NULL,
    codigo character varying NOT NULL,
    descripcion character varying NOT NULL,
    proveedor character varying,
    tipo_documento character varying,
    numero_documento character varying,
    registro_sanitario character varying,
    lote character varying,
    fabricante character varying,
    categoria_ingreso character varying,
    procedencia character varying,
    unidad character varying DEFAULT 'UND'::character varying NOT NULL,
    unidad_otro character varying,
    um character varying,
    temperatura_min_c numeric,
    temperatura_max_c numeric,
    observaciones text,
    activo smallint DEFAULT 1 NOT NULL,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    fecha_documento date,
    unidad_medida character varying,
    cliente_id integer,
    proveedor_ruc character varying,
    cliente_ruc character varying
);

